contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient) public payable {
        require(recipient != address(0));

        address beforeOwner = c.owner();
        uint256 beforeBal = address(c).balance;

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // msg.sender is this test contract, and this contract deployed c, so msg.sender != owner in general.
        // The rule: if the caller is not the owner, the call must revert; if it succeeds, the full balance moves out.
        if (beforeOwner == address(this)) {
            assert(!reverted);
            assert(beforeBal == 0 || address(c).balance == 0);
        } else {
            assert(reverted);
            assert(address(c).balance == beforeBal);
        }
    }

    receive() external payable {}
}

