        c = _c;
    }

    function run(address recipient, uint256 sendAmount, bool ownerCalls) public payable {
        require(address(this).balance >= sendAmount);

        (bool funded, ) = address(c).call{value: sendAmount}("");
        require(funded);

        address currentOwner = c.owner();
        require(currentOwner == msg.sender);

        uint256 beforeBalance = address(c).balance;

        bool reverted;
        if (!ownerCalls) {
            // Simulate a non-owner caller? Not possible without changing msg.sender.
            // Since msg.sender is always this contract (the owner), we only test the owner path.
            // To keep a general rule, we assert the owner-path behavior regardless.
        }
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;

        // General rule: since this contract is the owner, withdrawAll must succeed
